using System;
using System.IO;
using System.Text;
using UnityEngine;

/// <summary>
/// Loads the versioned, double-precision DE440s cache generated by
/// Tools/Ephemeris/preprocess_de440_cache.py. The cache is visualization data;
/// scientific consumers should use direct SPICE evaluation or a denser cache.
/// </summary>
[DisallowMultipleComponent]
public sealed class EphemerisDataProvider : MonoBehaviour
{
    private const string ExpectedMagic = "LUNEPH1\0";
    private const int ExpectedVersion = 1;
    private const int ExpectedHeaderBytes = 24;
    private const int ExpectedRecordBytes = 144;
    private const int MaximumRecordCount = 1_000_000;

    [SerializeField] private string cacheRelativePath = "CelestialEphemeris/de440s_daily_v1.bin";

    private struct Sample
    {
        public long utcTicks;
        public double etSeconds;
        public DoubleVector3 earthPositionKm;
        public DoubleVector3 earthVelocityKmPerSecond;
        public DoubleVector3 moonPositionKm;
        public DoubleVector3 moonVelocityKmPerSecond;
        public DoubleQuaternion moonBodyToJ2000;
    }

    private Sample[] _samples;

    public bool IsLoaded => _samples != null && _samples.Length > 1;
    public int SampleCount => _samples != null ? _samples.Length : 0;
    public string CachePath => Path.Combine(Application.streamingAssetsPath, cacheRelativePath);
    public double StartEtSeconds => IsLoaded ? _samples[0].etSeconds : double.NaN;
    public double EndEtSeconds => IsLoaded ? _samples[_samples.Length - 1].etSeconds : double.NaN;
    public DateTime StartUtc => IsLoaded ? new DateTime(_samples[0].utcTicks, DateTimeKind.Utc) : DateTime.MinValue;
    public DateTime EndUtc => IsLoaded ? new DateTime(_samples[_samples.Length - 1].utcTicks, DateTimeKind.Utc) : DateTime.MinValue;

    private void Awake()
    {
        if (!TryLoad(out string error))
            Debug.LogError($"[{nameof(EphemerisDataProvider)}] Could not load ephemeris cache: {error}", this);
    }

    public bool TryLoad(out string error)
    {
        error = null;
        if (IsLoaded)
            return true;

        try
        {
            string path = CachePath;
            if (!File.Exists(path))
                throw new FileNotFoundException("Ephemeris cache was not found.", path);

            using (FileStream stream = File.Open(path, FileMode.Open, FileAccess.Read, FileShare.Read))
            using (BinaryReader reader = new BinaryReader(stream, Encoding.ASCII, leaveOpen: false))
            {
                string magic = Encoding.ASCII.GetString(reader.ReadBytes(8));
                int version = reader.ReadInt32();
                int recordBytes = reader.ReadInt32();
                ulong rawCount = reader.ReadUInt64();

                if (!string.Equals(magic, ExpectedMagic, StringComparison.Ordinal))
                    throw new InvalidDataException($"Unexpected cache signature '{magic}'.");
                if (version != ExpectedVersion)
                    throw new InvalidDataException($"Cache version {version} is not supported.");
                if (recordBytes != ExpectedRecordBytes)
                    throw new InvalidDataException($"Cache record size {recordBytes} is not supported.");
                if (rawCount < 2 || rawCount > MaximumRecordCount)
                    throw new InvalidDataException($"Cache record count {rawCount} is outside the supported range.");

                int count = checked((int)rawCount);
                long expectedLength = ExpectedHeaderBytes + (long)count * ExpectedRecordBytes;
                if (stream.Length != expectedLength)
                    throw new InvalidDataException(
                        $"Cache length is {stream.Length} bytes; expected {expectedLength} bytes.");

                Sample[] loaded = new Sample[count];
                for (int i = 0; i < count; i++)
                {
                    Sample sample = new Sample
                    {
                        utcTicks = reader.ReadInt64(),
                        etSeconds = reader.ReadDouble(),
                        earthPositionKm = ReadVector(reader),
                        earthVelocityKmPerSecond = ReadVector(reader),
                        moonPositionKm = ReadVector(reader),
                        moonVelocityKmPerSecond = ReadVector(reader),
                        moonBodyToJ2000 = new DoubleQuaternion(
                            reader.ReadDouble(), reader.ReadDouble(), reader.ReadDouble(), reader.ReadDouble())
                    };

                    if (sample.utcTicks < DateTime.MinValue.Ticks || sample.utcTicks > DateTime.MaxValue.Ticks)
                        throw new InvalidDataException($"Invalid UTC tick value at record {i}.");
                    if (!IsFinite(sample.etSeconds) || !sample.earthPositionKm.IsFinite ||
                        !sample.earthVelocityKmPerSecond.IsFinite || !sample.moonPositionKm.IsFinite ||
                        !sample.moonVelocityKmPerSecond.IsFinite || !sample.moonBodyToJ2000.IsFinite)
                        throw new InvalidDataException($"Non-finite value at record {i}.");

                    double quaternionNorm = sample.moonBodyToJ2000.Magnitude;
                    if (quaternionNorm < 0.999 || quaternionNorm > 1.001)
                        throw new InvalidDataException($"Moon orientation quaternion is not normalized at record {i}.");

                    if (i > 0 && (sample.utcTicks <= loaded[i - 1].utcTicks ||
                                  sample.etSeconds <= loaded[i - 1].etSeconds))
                        throw new InvalidDataException($"Cache time is not strictly increasing at record {i}.");

                    loaded[i] = sample;
                }

                _samples = loaded;
            }

            Debug.Log(
                $"[{nameof(EphemerisDataProvider)}] Loaded {_samples.Length:N0} DE440s samples " +
                $"({StartUtc:yyyy-MM-dd} to {EndUtc:yyyy-MM-dd} UTC).", this);
            return true;
        }
        catch (Exception ex)
        {
            _samples = null;
            error = ex.Message;
            return false;
        }
    }

    /// <summary>
    /// Converts a UTC selection to ET by interpolating the exact daily UTC/ET anchors.
    /// This is intended for display animation, not precision geometry at leap seconds.
    /// </summary>
    public bool TryGetEtFromUtc(DateTime utc, out double etSeconds, out string error)
    {
        etSeconds = 0.0;
        error = null;
        if (!TryEnsureLoaded(out error))
            return false;

        long ticks = NormalizeUtc(utc).Ticks;
        if (ticks < _samples[0].utcTicks || ticks > _samples[_samples.Length - 1].utcTicks)
        {
            error = $"UTC time must be between {StartUtc:yyyy-MM-dd} and {EndUtc:yyyy-MM-dd}.";
            return false;
        }

        int left = FindUtcInterval(ticks);
        if (left >= _samples.Length - 1 || ticks == _samples[left].utcTicks)
        {
            etSeconds = _samples[left].etSeconds;
            return true;
        }

        Sample a = _samples[left];
        Sample b = _samples[left + 1];
        double u = (double)(ticks - a.utcTicks) / (double)(b.utcTicks - a.utcTicks);
        etSeconds = Lerp(a.etSeconds, b.etSeconds, u);
        return true;
    }

    public bool TryGetAtUtc(DateTime utc, out EphemerisState state, out string error)
    {
        state = default;
        if (!TryGetEtFromUtc(utc, out double et, out error))
            return false;
        return TryGetAtEt(et, out state, out error);
    }

    /// <summary>Interpolates a state at ET using position/velocity Hermite interpolation and quaternion slerp.</summary>
    public bool TryGetAtEt(double etSeconds, out EphemerisState state, out string error)
    {
        state = default;
        error = null;
        if (!TryEnsureLoaded(out error))
            return false;
        if (!IsFinite(etSeconds) || etSeconds < StartEtSeconds || etSeconds > EndEtSeconds)
        {
            error = $"ET must be within the cache coverage [{StartEtSeconds:F3}, {EndEtSeconds:F3}] seconds.";
            return false;
        }

        int left = FindEtInterval(etSeconds);
        Sample a = _samples[left];
        if (left == _samples.Length - 1 || etSeconds == a.etSeconds)
        {
            state = ToState(a);
            return true;
        }

        Sample b = _samples[left + 1];
        double duration = b.etSeconds - a.etSeconds;
        double u = (etSeconds - a.etSeconds) / duration;

        DoubleVector3 earthPosition = HermitePosition(
            a.earthPositionKm, a.earthVelocityKmPerSecond,
            b.earthPositionKm, b.earthVelocityKmPerSecond, u, duration);
        DoubleVector3 earthVelocity = HermiteVelocity(
            a.earthPositionKm, a.earthVelocityKmPerSecond,
            b.earthPositionKm, b.earthVelocityKmPerSecond, u, duration);
        DoubleVector3 moonPosition = HermitePosition(
            a.moonPositionKm, a.moonVelocityKmPerSecond,
            b.moonPositionKm, b.moonVelocityKmPerSecond, u, duration);
        DoubleVector3 moonVelocity = HermiteVelocity(
            a.moonPositionKm, a.moonVelocityKmPerSecond,
            b.moonPositionKm, b.moonVelocityKmPerSecond, u, duration);

        long utcTicks = a.utcTicks + (long)Math.Round((b.utcTicks - a.utcTicks) * u);
        state = new EphemerisState(
            utcTicks, etSeconds,
            earthPosition, earthVelocity,
            moonPosition, moonVelocity,
            DoubleQuaternion.Slerp(a.moonBodyToJ2000, b.moonBodyToJ2000, u));
        return true;
    }

    private bool TryEnsureLoaded(out string error)
    {
        if (IsLoaded)
        {
            error = null;
            return true;
        }
        return TryLoad(out error);
    }

    private int FindUtcInterval(long ticks)
    {
        int low = 0;
        int high = _samples.Length - 1;
        while (low <= high)
        {
            int mid = low + ((high - low) >> 1);
            long value = _samples[mid].utcTicks;
            if (value == ticks) return mid;
            if (value < ticks) low = mid + 1;
            else high = mid - 1;
        }
        return Math.Max(0, Math.Min(_samples.Length - 2, high));
    }

    private int FindEtInterval(double etSeconds)
    {
        int low = 0;
        int high = _samples.Length - 1;
        while (low <= high)
        {
            int mid = low + ((high - low) >> 1);
            double value = _samples[mid].etSeconds;
            if (value == etSeconds) return mid;
            if (value < etSeconds) low = mid + 1;
            else high = mid - 1;
        }
        return Math.Max(0, Math.Min(_samples.Length - 2, high));
    }

    private static EphemerisState ToState(Sample sample)
    {
        return new EphemerisState(
            sample.utcTicks, sample.etSeconds,
            sample.earthPositionKm, sample.earthVelocityKmPerSecond,
            sample.moonPositionKm, sample.moonVelocityKmPerSecond,
            sample.moonBodyToJ2000);
    }

    private static DoubleVector3 ReadVector(BinaryReader reader)
        => new DoubleVector3(reader.ReadDouble(), reader.ReadDouble(), reader.ReadDouble());

    private static DoubleVector3 HermitePosition(
        DoubleVector3 p0, DoubleVector3 v0, DoubleVector3 p1, DoubleVector3 v1,
        double u, double duration)
    {
        double u2 = u * u;
        double u3 = u2 * u;
        double h00 = 2.0 * u3 - 3.0 * u2 + 1.0;
        double h10 = u3 - 2.0 * u2 + u;
        double h01 = -2.0 * u3 + 3.0 * u2;
        double h11 = u3 - u2;
        return p0 * h00 + v0 * (duration * h10) + p1 * h01 + v1 * (duration * h11);
    }

    private static DoubleVector3 HermiteVelocity(
        DoubleVector3 p0, DoubleVector3 v0, DoubleVector3 p1, DoubleVector3 v1,
        double u, double duration)
    {
        double u2 = u * u;
        double dh00 = -6.0 * u2 + 6.0 * u;
        double dh10 = 3.0 * u2 - 4.0 * u + 1.0;
        double dh01 = 6.0 * u2 - 6.0 * u;
        double dh11 = 3.0 * u2 - 2.0 * u;
        return (p0 * dh00 + p1 * dh01) / duration + v0 * dh10 + v1 * dh11;
    }

    private static DateTime NormalizeUtc(DateTime value)
    {
        if (value.Kind == DateTimeKind.Local)
            return value.ToUniversalTime();
        return DateTime.SpecifyKind(value, DateTimeKind.Utc);
    }

    private static double Lerp(double a, double b, double t) => a + (b - a) * t;
    private static bool IsFinite(double value) => !double.IsNaN(value) && !double.IsInfinity(value);
}

[Serializable]
public struct EphemerisState
{
    public long utcTicks;
    public double etSeconds;
    public DoubleVector3 earthHeliocentricPositionKm;
    public DoubleVector3 earthHeliocentricVelocityKmPerSecond;
    public DoubleVector3 moonHeliocentricPositionKm;
    public DoubleVector3 moonHeliocentricVelocityKmPerSecond;
    public DoubleQuaternion moonBodyToJ2000;

    public DateTime UtcDateTime => new DateTime(utcTicks, DateTimeKind.Utc);

    public EphemerisState(
        long ticks, double et,
        DoubleVector3 earthPosition, DoubleVector3 earthVelocity,
        DoubleVector3 moonPosition, DoubleVector3 moonVelocity,
        DoubleQuaternion moonRotation)
    {
        utcTicks = ticks;
        etSeconds = et;
        earthHeliocentricPositionKm = earthPosition;
        earthHeliocentricVelocityKmPerSecond = earthVelocity;
        moonHeliocentricPositionKm = moonPosition;
        moonHeliocentricVelocityKmPerSecond = moonVelocity;
        moonBodyToJ2000 = moonRotation;
    }
}

[Serializable]
public struct DoubleVector3
{
    public double x;
    public double y;
    public double z;

    public DoubleVector3(double xValue, double yValue, double zValue)
    {
        x = xValue;
        y = yValue;
        z = zValue;
    }

    public bool IsFinite => IsFiniteValue(x) && IsFiniteValue(y) && IsFiniteValue(z);
    public Vector3 ToUnityVector3() => new Vector3((float)x, (float)y, (float)z);

    public static DoubleVector3 operator +(DoubleVector3 a, DoubleVector3 b)
        => new DoubleVector3(a.x + b.x, a.y + b.y, a.z + b.z);
    public static DoubleVector3 operator -(DoubleVector3 a, DoubleVector3 b)
        => new DoubleVector3(a.x - b.x, a.y - b.y, a.z - b.z);
    public static DoubleVector3 operator *(DoubleVector3 value, double scale)
        => new DoubleVector3(value.x * scale, value.y * scale, value.z * scale);
    public static DoubleVector3 operator /(DoubleVector3 value, double scale)
        => new DoubleVector3(value.x / scale, value.y / scale, value.z / scale);

    private static bool IsFiniteValue(double value) => !double.IsNaN(value) && !double.IsInfinity(value);
}

[Serializable]
public struct DoubleQuaternion
{
    public double x;
    public double y;
    public double z;
    public double w;

    public DoubleQuaternion(double xValue, double yValue, double zValue, double wValue)
    {
        x = xValue;
        y = yValue;
        z = zValue;
        w = wValue;
    }

    public bool IsFinite => IsFiniteValue(x) && IsFiniteValue(y) && IsFiniteValue(z) && IsFiniteValue(w);
    public double Magnitude => Math.Sqrt(x * x + y * y + z * z + w * w);

    public Quaternion ToUnityQuaternion() => new Quaternion((float)x, (float)y, (float)z, (float)w);

    public DoubleVector3 Rotate(DoubleVector3 value)
    {
        // q*v*q^-1, evaluated in double precision before the rendering conversion.
        double tx = 2.0 * (y * value.z - z * value.y);
        double ty = 2.0 * (z * value.x - x * value.z);
        double tz = 2.0 * (x * value.y - y * value.x);
        return new DoubleVector3(
            value.x + w * tx + (y * tz - z * ty),
            value.y + w * ty + (z * tx - x * tz),
            value.z + w * tz + (x * ty - y * tx));
    }

    public static DoubleQuaternion FromUnity(Quaternion value)
    {
        double magnitude = Math.Sqrt(value.x * value.x + value.y * value.y + value.z * value.z + value.w * value.w);
        if (magnitude <= 0.0)
            return new DoubleQuaternion(0.0, 0.0, 0.0, 1.0);
        return new DoubleQuaternion(
            value.x / magnitude, value.y / magnitude, value.z / magnitude, value.w / magnitude);
    }

    public static DoubleQuaternion Slerp(DoubleQuaternion a, DoubleQuaternion b, double t)
    {
        double dot = a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
        if (dot < 0.0)
        {
            b = new DoubleQuaternion(-b.x, -b.y, -b.z, -b.w);
            dot = -dot;
        }

        dot = Math.Max(-1.0, Math.Min(1.0, dot));
        if (dot > 0.9995)
            return Normalize(new DoubleQuaternion(
                a.x + (b.x - a.x) * t,
                a.y + (b.y - a.y) * t,
                a.z + (b.z - a.z) * t,
                a.w + (b.w - a.w) * t));

        double theta = Math.Acos(dot);
        double sinTheta = Math.Sin(theta);
        double weightA = Math.Sin((1.0 - t) * theta) / sinTheta;
        double weightB = Math.Sin(t * theta) / sinTheta;
        return Normalize(new DoubleQuaternion(
            weightA * a.x + weightB * b.x,
            weightA * a.y + weightB * b.y,
            weightA * a.z + weightB * b.z,
            weightA * a.w + weightB * b.w));
    }

    private static DoubleQuaternion Normalize(DoubleQuaternion value)
    {
        double norm = value.Magnitude;
        return norm <= 0.0
            ? new DoubleQuaternion(0.0, 0.0, 0.0, 1.0)
            : new DoubleQuaternion(value.x / norm, value.y / norm, value.z / norm, value.w / norm);
    }

    private static bool IsFiniteValue(double value) => !double.IsNaN(value) && !double.IsInfinity(value);
}
